def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = OrderedDict()
        cache_times = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else (args, frozenset(kwargs.items()))
            if key in cache:
                if timer() - cache_times[key] < ttl:
                    return cache[key]
                else:
                    del cache[key]
                    del cache_times[key]

            if len(cache) >= maxsize:
                cache.popitem(last=False)
                cache_times.popitem(last=False)

            result = func(*args, **kwargs)
            cache[key] = result
            cache_times[key] = timer()
            return result

        return wrapper

    return decorator

