def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = OrderedDict()
        hit = 0
        miss = 0

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hit, miss
            key = args if not typed else (args, tuple(kwargs.items()))
            if key in cache:
                hit += 1
                cache.move_to_end(key)
                return cache[key]
            else:
                miss += 1
                result = func(*args, **kwargs)
                cache[key] = result
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result

        wrapper.cache_info = lambda: (hit, miss, maxsize, len(cache))
        return wrapper

    return decorator

