    def decorator(func):
        if maxsize <= 0:
            raise ValueError("maxsize must be a positive integer")

        cache = OrderedDict()
        frequency = Counter()
        min_freq = 0

        def wrapper(*args, **kwargs):
            key = (func, args, tuple(kwargs.items())) if typed else (func, tuple(args), tuple(kwargs.items()))
            if key in cache:
                frequency[key] += 1
                cache.move_to_end(key)
                return cache[key]
            if len(cache) >= maxsize:
                while cache:
                    k, v = cache.popitem(last=False)
                    if frequency[k] == min_freq:
                        frequency.pop(k)
                        break
            cache[key] = func(*args, **kwargs)
            frequency[key] = 1
            min_freq = 1
            return cache[key]

        return wrapper

    return decorator

