def _legacy_mergeOrderings(orderings):
    if not orderings:
        return []

    merged = orderings[0].copy()
    for ordering in orderings[1:]:
        i = 0
        while i < len(merged) and i < len(ordering) and merged[i] == ordering[i]:
            i += 1
        merged[i:] = ordering[i:]

    return merged

