    valid_files = set(manifest_files)
    for file_info in fixity['files']:
        if not isinstance(file_info, dict):
            raise ValueError("Each file in fixity block must be a dictionary")

        if 'filename' not in file_info:
            raise ValueError("Each file in fixity block must contain a 'filename' key")

        if not isinstance(file_info['filename'], str):
            raise ValueError("Filename in fixity block must be a string")

        if file_info['filename'] not in valid_files:
            raise ValueError(f"File '{file_info['filename']}' in fixity block is not listed in the manifest")

        if 'checksum' not in file_info:
            raise ValueError("Each file in fixity block must contain a 'checksum' key")

        if not isinstance(file_info['checksum'], str):
            raise ValueError("Checksum in fixity block must be a string")

    return True

