def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple):
            op, *operands = expr
            if op == 'and':
                if len(operands) == 2:
                    a, b = operands
                    if isinstance(b, tuple) and b[0] == 'or' and len(b) == 3 and b[1] == a:
                        return a
            elif op == 'or':
                if len(operands) == 2:
                    a, b = operands
                    if isinstance(b, tuple) and b[0] == 'and' and len(b) == 3 and b[1] == a:
                        return a
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, tuple):
            op, *operands = expr
            if op == 'and':
                if len(operands) == 2:
                    a, b = operands
                    if isinstance(b, tuple) and b[0] == 'or' and len(b) == 3 and b[1] == 'not' and b[2] == a:
                        return b[2]
            elif op == 'or':
                if len(operands) == 2:
                    a, b = operands
                    if isinstance(b, tuple) and b[0] == 'and' and len(b) == 3 and b[1] == 'not' and b[2] == a:
                        return b[2]
        return expr

    result = []
    for expr in args:
        expr = apply_absorption(expr)
        expr = apply_negative_absorption(expr)
        result.append(expr)
    return result

