def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces or not style:
        raise ValueError("Both pieces and style must be non-empty")

    if not isinstance(pieces, list) or not all(isinstance(p, str) for p in pieces):
        raise ValueError("Pieces must be a list of strings")

    if not isinstance(style, str):
        raise ValueError("Style must be a string")

    if style == "plain":
        return "".join(pieces)
    elif style == "upper":
        return "".join(p.upper() for p in pieces)
    elif style == "lower":
        return "".join(p.lower() for p in pieces)
    elif style == "title":
        return "".join(p.title() for p in pieces)
    else:
        raise ValueError("Unsupported style")

