def validate_version_inventories(self, version_dirs):
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    root_inventory = None
    content_digests = set()

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory not found for version {version_dir}")

        with open(inventory_path, 'r') as file:
            inventory = file.read()
            if root_inventory is None:
                root_inventory = inventory
            else:
                if inventory != root_inventory:
                    content_digests.update(self.calculate_content_digests(inventory))

    return content_digests

