def find_path_type(path):
    try:
        import os
        if not os.path.exists(path):
            return "path does not exist"
        if os.path.isfile(path):
            return "file"
        if os.path.isdir(path):
            namaste_file_path = os.path.join(path, "0=*")
            if os.path.exists(namaste_file_path):
                with open(namaste_file_path, 'r') as file:
                    first_line = file.readline().strip()
                    if first_line == "OCFL Version: 1.0":
                        return "root"
                    elif first_line == "OCFL Object Version: 1.0":
                        return "object"
        return "unknown directory type"
    except Exception as e:
        return f"error: {str(e)}"

