def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if not all(isinstance(char, str) and len(char) == 1 for char in alphabet):
        raise ValueError("Alphabet must contain single characters")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Padding must be a non-negative integer")

    if number == 0:
        return alphabet[0] if padding is None or padding == 0 else alphabet[0] * padding

    digits = []
    while number > 0:
        digits.append(number % len(alphabet))
        number //= len(alphabet)

    result = ''.join(alphabet[digit] for digit in reversed(digits))

    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

