def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_content: bin_content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("Invalid get_coordinate value. Must be 'left', 'right', or 'middle'.")

    if len(field_names) != 2:
        raise ValueError("Invalid number of field_names. Must be 2.")

    if scale is not None and scale not in [True, False]:
        raise ValueError("Invalid scale value. Must be True or False.")

    graph_points = []
    for bin_index, bin_content in enumerate(hist):
        if make_value(bin_content) is None:
            continue

        if get_coordinate == "left":
            coordinate = bin_index
        elif get_coordinate == "right":
            coordinate = bin_index + 1
        elif get_coordinate == "middle":
            coordinate = bin_index + 0.5

        graph_point = {field_names[0]: coordinate, field_names[1]: make_value(bin_content)}
        graph_points.append(graph_point)

    if scale is True:
        graph_scale = hist.scale
    else:
        graph_scale = None

    return graph_points, graph_scale

