def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import Invalid, implementer, provider, providedBy, implementedBy

    if not tentative and not providedBy(candidate, iface):
        raise Invalid(f"Candidate does not claim to provide interface {iface}")

    candidate_methods = set(dir(candidate))
    required_methods = set(iface.names())
    missing_methods = required_methods - candidate_methods

    if missing_methods:
        raise Invalid(f"Candidate is missing methods: {', '.join(missing_methods)}")

    for method_name in required_methods:
        method = getattr(candidate, method_name)
        if not callable(method):
            raise Invalid(f"Method {method_name} is not callable")

    candidate_attributes = set(dir(candidate))
    required_attributes = set(iface.names())
    missing_attributes = required_attributes - candidate_attributes

    if missing_attributes:
        raise Invalid(f"Candidate is missing attributes: {', '.join(missing_attributes)}")

    return True

