def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    result = []
    current_tag = []

    for char in text:
        if char == '`':
            in_code_block = not in_code_block
        elif not in_code_block:
            if char == '@':
                current_tag.append(char)
            elif current_tag:
                current_tag.append(char)
                if char == ' ' or char == '\n':
                    tag = ''.join(current_tag).strip()
                    tags.add(tag)
                    if replacer:
                        result.append(replacer(tag))
                    else:
                        result.append(tag)
                    current_tag = []
                else:
                    result.append(char)
            else:
                result.append(char)
        else:
            result.append(char)

    if current_tag:
        tag = ''.join(current_tag).strip()
        tags.add(tag)
        if replacer:
            result.append(replacer(tag))
        else:
            result.append(tag)

    return tags, ''.join(result)

