    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Step 1: Validate the input
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")

    # Step 2: Retrieve the parser for the specified command
    try:
        parser = self.get_parser(command_name)
    except KeyError:
        raise ValueError(f"No parser found for command: {command_name}")

    # Step 3: Extract the options from the parser
    options = []
    for action in parser._actions:
        if isinstance(action, argparse._StoreAction):
            options.append({
                'name': action.dest,
                'help': action.help,
                'type': action.type.__name__ if action.type else 'str',
                'required': action.required
            })

    return options

